package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.*;import com.openggf.game.soniccd.media.CdProgramAssets;import com.openggf.game.soniccd.objects.*;
import org.junit.jupiter.api.BeforeAll;import org.junit.jupiter.api.Test;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Tests FIRST/allJavaUNRUN. Source DATA alone grants no live World or art owner. */
class TestCdOriginalTtSpringSource {
 private static CdProgrammeData programme,foreign,past;private static CdProgrammeObjectSource source;
 @BeforeAll static void originalReader()throws Exception{String root=System.getProperty("soniccd.media.root","");assertFalse(root.isBlank(),"Original USA media is required");try(var disc=CdProgramAssets.open(Path.of(root,"USA","Sonic CD (US).cue"),Optional.of(CdReleaseVariant.USA),Optional.empty())){assertEquals(CdR4DataLayout.USA_DISC_SHA256,disc.identity().normalizedSha256());programme=CdProgrammeData.open(disc,CdR4DataLayout.Programme.R41A);foreign=CdProgrammeData.open(disc,CdR4DataLayout.Programme.R41A);past=CdProgrammeData.open(disc,CdR4DataLayout.Programme.R41B);}source=programme.objectSource();}
 @Test void sixOriginalViewsHaveTheirOwnAddressesLengthsAndHashes(){
  check(CdProgrammeObjectSource.Table.SPRING_MAPPINGS,0x208FF2,199,"f1c0f43ac8925447d88d33fed86d98062d4156d7430802e4c0de37ed620753fd");check(CdProgrammeObjectSource.Table.SPRING_ANIMATIONS,0x208FE4,14,"7f641336673d1419b30d9555fa0e2ff3a12a95811b26f2d12d96e8b32befb6b5");check(CdProgrammeObjectSource.Table.SPRING_SPEEDS,0x208D3A,4,"5eda02f69ae1d12606f936787ccebdac8133522694513985847a115cc00f2621");check(CdProgrammeObjectSource.Table.MOVING_SPRING_MAPPINGS,0x2090C0,16,"f06f49cb0a71706485ede6030456b96b0523e69e3545ba6bc7094076698f459d");check(CdProgrammeObjectSource.Table.MOVING_SPRING_ANIMATIONS,0x2090BA,6,"e8b2932927462b357fa2e0666e939c3cd3031a290c5be159b9f9321c3021547a");check(CdProgrammeObjectSource.Table.SPRING_TILE_HELPER,0x20C050,2,"1ceeabf0c6a5a30bad12cdac0e3ab015a7188a42e6aebb556aad00bb9cd693ad");
 }
 @Test void cachedFiniteProfilesKeepActual199ThreeRootsAndTheLiteralNoStoreHelper(){var p=source.springProfile();assertSame(p,source.springProfile());assertEquals(0x208FF2,p.mappingsAddress());assertEquals(0,p.vertical().mappingTableOffset());assertEquals(6,p.horizontal().mappingTableOffset());assertEquals(80,p.diagonal().mappingTableOffset());for(var v:List.of(p.vertical(),p.horizontal(),p.diagonal())){assertEquals(199,v.mappings().length());assertEquals(14,v.animationTable().length());assertEquals(3,v.mappingFrames().size());}assertEquals(0x520,p.diagonalTileWord());assertEquals((short)0xF000,(short)p.speedWords().unsignedWord(0));assertEquals((short)0xF600,(short)p.speedWords().unsignedWord(2));source.requireSpringTileHelperNoop();assertEquals(0x4E75,source.view(CdProgrammeObjectSource.Table.SPRING_TILE_HELPER).bytes().unsignedWord(0));var m=source.movingSpringData();assertSame(m,source.movingSpringData());assertEquals(0x2090C0,m.mappingsAddress());assertEquals(16,m.visual().mappings().length());assertEquals(6,m.visual().animationTable().length());}
 @Test void mapperKeepsAllThreeSpringRootsAndTheIndependentMovingRoot(){var m=source.mappings();for(int root:new int[]{0x208FF2,0x208FF8,0x209042}){for(int n=0;n<3;n++)assertInstanceOf(CdObjectDrawQueue.FrameMapping.class,m.resolve(root,false,n));assertThrows(UnsupportedOperationException.class,()->m.resolve(root,false,3));}for(int n=0;n<2;n++)assertInstanceOf(CdObjectDrawQueue.FrameMapping.class,m.resolve(0x2090C0,false,n));assertThrows(UnsupportedOperationException.class,()->m.resolve(0x2090C0,false,2));assertThrows(UnsupportedOperationException.class,()->m.resolve(0x208FF4,false,0));}
 @Test void nativeDispatchAndInitialFamilyDiagnosticArePreserved(){var d=source.view(CdProgrammeObjectSource.Table.DISPATCH).bytes();assertEquals(0x208C00,d.unsignedLong((0x0A-1)*4));assertEquals(0x208AB4,d.unsignedLong((0x0F-1)*4));assertEquals(List.of(4,0x0B,0x10,0x19,0x1C,0x20,0x21,0x22,0x2B,0x2F,0x32,0x34,0x3C),source.initialFamilyIds());assertEquals(31,CdProgrammeObjectSource.Table.COLLAPSE_MAPPINGS.ordinal());assertEquals(42,CdProgrammeObjectSource.Table.MONITOR_ANIMATIONS.ordinal());assertTrue(CdProgrammeObjectSource.Table.SPRING_MAPPINGS.ordinal()>42);}
 @Test void equalForeignReaderCannotBorrowPlacementAndOtherPeriodsStayUnadmitted(){var p=new CdObjectPlacementRuntime(programme.placements());source.requirePlacement(p);assertNotSame(source.springProfile(),foreign.objectSource().springProfile());assertNotSame(source.movingSpringData(),foreign.objectSource().movingSpringData());assertThrows(IllegalArgumentException.class,()->foreign.objectSource().requirePlacement(p));assertThrows(UnsupportedOperationException.class,()->past.objectSource());}
 private static void check(CdProgrammeObjectSource.Table t,int at,int length,String hash){var v=source.view(t);assertSame(v,source.view(t));assertEquals(at,v.nativeAddress());assertEquals(length,v.bytes().length());assertEquals(hash,CdR11aProfile.sha256(v.bytes().copy()));}
}
